function fwc_recover_test()
%FWC_RECOVER_TEST  Plumbing test of CalVshLinTrans and fwc_recover without HFSS data.
% (1) operator: adjoint <A s, z> = <s, A' z>, multSq against |H|.^2 from a dense H, ana(syn(s)) = s.
% (2) noiseless-model recovery: AUT modes from Solve A (L = 12), random smooth-in-frequency probe responses
%     R for 32 ports, data generated by the SAME operator (the model is exact), 4 frequencies, IC m/n 0.6.
%     Expect a low NMSE (the solver and prior work on this operator), not a physics result.
cpr_settings('paper');   % run setup.m first
maxNumCompThreads(2); rng(7);
nf = 4; np = 32; nrot = 32; L = 12;
T = read_aedt_table(fullfile(cpr_paths().data, 'hfss_fullarc', 'autalone_offset_farfield.csv'));
Aut = fwc_aut_modes(T, L);
f = Aut.freq(1:nf); modes = Aut.modes; nm = size(modes, 1);
R0 = (randn(np, nm) + 1i*randn(np, nm)) / sqrt(2*nm); R1 = (randn(np, nm) + 1i*randn(np, nm)) / sqrt(2*nm);
R = zeros(np, nm, nf);
for k = 1:nf, R(:, :, k) = R0 + 0.2*(k-1)/nf * R1; end
psi = (0:nrot-1) * 2*pi/nrot;
D = struct('R', R, 'modes', modes, 'psi', psi, 'f', f, 'aTrue', Aut.a(:, 1:nf));
% data from the model itself
X = zeros(np, nrot, nf);
for k = 1:nf
    E = exp(-1i * modes(:, 2).' .* psi(:));
    for l = 1:nrot, X(:, l, k) = R(:, :, k) * (D.aTrue(:, k) .* E(l, :).'); end
end
D.Xring = X;
% (1) operator checks on a small reading set
c = cpr_cfg('arch', 'IC', 'ratio', 0.6, 'snrdB', 100);
Dm = struct('Xring', X, 'f', f, 'nlegsAvail', 0, 'Xleg', [], 'anchor', 1, 'legShift', 1);
S = make_readings_fw(c, Dm, 1, 'ideal');
G = cell(1, nf);
for k = 1:nf
    E = exp(-1i * modes(:, 2).' .* psi(:)); Gf = zeros(np*nrot, nm);
    for l = 1:nrot, Gf((l-1)*np + (1:np), :) = R(:, :, k) .* E(l, :); end
    G{k} = Gf;
end
A = CalVshLinTrans(S.Phi, G, cpr_basis('dct', f, 3e-9));
s = randn(nm*nf, 1) + 1i*randn(nm*nf, 1); zz = randn(S.m, 1) + 1i*randn(S.m, 1);
fprintf('adjoint test: %.2e (relative)\n', abs(zz' * A.mult(s) - (A.multTr(zz))' * s) / abs(zz' * A.mult(s)));
fprintf('ana(syn(s)) = s: %.2e\n', norm(A.ana(A.syn(s)) - s) / norm(s));
Hd = zeros(S.m, nm*nf); for j = 1:nm*nf, e = zeros(nm*nf, 1); e(j) = 1; Hd(:, j) = A.mult(e); end
v = rand(nm*nf, 1);
fprintf('multSq vs dense |H|.^2: %.2e\n', norm(A.multSq(v) - abs(Hd).^2 * v) / norm(abs(Hd).^2 * v));
fprintf('model consistency: Phi * probes(aTrue) vs Phi * Xring: %.2e\n', norm(S.Phi * A.probes(D.aTrue(:)) - S.Phi * X(:)) / norm(S.Phi * X(:)));
% (2) recovery
c.verbose = true;
r = fwc_recover(c, 1, D);
fprintf('recovery (exact model, %d freqs, m = %d): NMSE per-freq scale %.1f dB, per-freq phase %.1f dB, model %.1f dB, tries %d, %.0f s\n', ...
    nf, r.m, r.nmse.perfreqScale, r.nmse.perfreqPhase, r.nmse.model, r.info.numTry, r.time);
end
